1	"use client";
2	
3	import { useState } from "react";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Input } from "@/components/ui/input";
6	import { toast } from "sonner";
7	import { Loader2 } from "lucide-react";
8	import type { AuthPageConfig } from "@/hooks/useAuthPageConfig";
9	import { SocialAuthButtons } from "./SocialAuthButtons";
10	import { Divider } from "./Divider";
11	import { TrustBadges } from "./TrustBadges";
12	
13	interface SignInFormProps {
14	  config: AuthPageConfig;
15	  onSuccess?: () => void;
16	  onSwitchToSignUp: () => void;
17	  onForgotPassword: () => void;
18	}
19	
20	export function SignInForm({
21	  config,
22	  onSuccess,
23	  onSwitchToSignUp,
24	  onForgotPassword,
25	}: SignInFormProps) {
26	  const [email, setEmail] = useState("");
27	  const [password, setPassword] = useState("");
28	  const [loading, setLoading] = useState(false);
29	
30	  const handleSubmit = async (e: React.FormEvent) => {
31	    e.preventDefault();
32	    setLoading(true);
33	    try {
34	      const { error } = await supabase.auth.signInWithPassword({
35	        email,
36	        password,
37	      });
38	      if (error) {
39	        toast.error(error.message);
40	      } else {
41	        toast.success("Signed in successfully");
42	        onSuccess?.();
43	      }
44	    } catch {
45	      toast.error("An unexpected error occurred. Please try again.");
46	    } finally {
47	      setLoading(false);
48	    }
49	  };
50	
51	  const hasSso = config.google_auth_enabled || config.microsoft_auth_enabled;
52	
53	  return (
54	    <div className="flex w-full flex-col justify-center bg-background px-6 py-10 sm:px-10 lg:px-14">
55	      <div className="mx-auto w-full max-w-[400px]">
56	        {/* Mobile logo — visible only below md */}
57	        <div className="mb-8 flex items-center gap-2.5 md:hidden">
58	          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-auth-accent to-auth-accent/80 text-sm font-extrabold text-white">
59	            R
60	          </div>
61	          <span className="text-xl font-bold tracking-tight text-foreground">
62	            Rankora
63	          </span>
64	        </div>
65	
66	        {/* Header */}
67	        <div className="mb-7">
68	          <h1 className="text-2xl font-bold tracking-tight text-foreground sm:text-3xl">
69	            {config.signin_heading}
70	          </h1>
71	          <p className="mt-1.5 text-sm text-muted-foreground">
72	            {config.signin_subheading}
73	          </p>
74	        </div>
75	
76	        {/* SSO */}
77	        <SocialAuthButtons
78	          googleEnabled={config.google_auth_enabled}
79	          microsoftEnabled={config.microsoft_auth_enabled}
80	          mode="signin"
81	          disabled={loading}
82	        />
83	
84	        {hasSso && (
85	          <div className="my-5">
86	            <Divider />
87	          </div>
88	        )}
89	
90	        {/* Email / Password form */}
91	        <form onSubmit={handleSubmit} className="space-y-4">
92	          <div className="space-y-1.5">
93	            <label
94	              htmlFor="signin-email"
95	              className="text-sm font-medium text-foreground"
96	            >
97	              Email
98	            </label>
99	            <Input
100	              id="signin-email"
101	              type="email"
102	              value={email}
103	              onChange={(e) => setEmail(e.target.value)}
104	              placeholder="name@company.com"
105	              autoComplete="email"
106	              required
107	              disabled={loading}
108	              className="h-11 rounded-lg"
109	            />
110	          </div>
111	
112	          <div className="space-y-1.5">
113	            <label
114	              htmlFor="signin-password"
115	              className="text-sm font-medium text-foreground"
116	            >
117	              Password
118	            </label>
119	            <Input
120	              id="signin-password"
121	              type="password"
122	              value={password}
123	              onChange={(e) => setPassword(e.target.value)}
124	              placeholder="Enter your password"
125	              autoComplete="current-password"
126	              required
127	              disabled={loading}
128	              className="h-11 rounded-lg"
129	            />
130	          </div>
131	
132	          {/* Remember me + Forgot */}
133	          <div className="flex items-center justify-between">
134	            <label className="flex cursor-pointer items-center gap-2 text-sm text-muted-foreground">
135	              <input
136	                type="checkbox"
137	                defaultChecked
138	                className="h-4 w-4 rounded border-border accent-auth-accent"
139	              />
140	              Remember me
141	            </label>
142	            <button
143	              type="button"
144	              onClick={onForgotPassword}
145	              className="text-sm font-medium text-auth-accent hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 rounded-sm"
146	            >
147	              Forgot password?
148	            </button>
149	          </div>
150	
151	          {/* Submit */}
152	          <button
153	            type="submit"
154	            disabled={loading}
155	            className="relative mt-2 flex w-full items-center justify-center rounded-lg bg-auth-btn px-4 py-3 text-sm font-semibold text-white transition-all hover:-translate-y-px hover:bg-auth-btn-hover hover:shadow-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 active:translate-y-0 disabled:pointer-events-none disabled:opacity-50"
156	          >
157	            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
158	            Sign in
159	          </button>
160	        </form>
161	
162	        {/* Switch to signup */}
163	        <p className="mt-5 text-center text-sm text-muted-foreground">
164	          Don&apos;t have an account?{" "}
165	          <button
166	            type="button"
167	            onClick={onSwitchToSignUp}
168	            className="font-semibold text-auth-accent hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 rounded-sm"
169	          >
170	            Start free trial &rarr;
171	          </button>
172	        </p>
173	
174	        {/* Trust badges */}
175	        <div className="mt-6">
176	          <TrustBadges badges={config.trust_badges} />
177	        </div>
178	      </div>
179	    </div>
180	  );
181	}
