1	"use client";
2	
3	import { useState } from "react";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Input } from "@/components/ui/input";
6	import { toast } from "sonner";
7	import { Loader2 } from "lucide-react";
8	import type { AuthPageConfig } from "@/hooks/useAuthPageConfig";
9	import { SocialAuthButtons } from "./SocialAuthButtons";
10	import { Divider } from "./Divider";
11	import { TrustBadges } from "./TrustBadges";
12	
13	interface SignUpFormProps {
14	  config: AuthPageConfig;
15	  onSuccess?: () => void;
16	  onSwitchToSignIn: () => void;
17	}
18	
19	type Step = 1 | 2 | 3;
20	
21	const STEP_LABELS: Record<Step, string> = {
22	  1: "just your email to start",
23	  2: "what should we call you?",
24	  3: "set a secure password",
25	};
26	
27	export function SignUpForm({
28	  config,
29	  onSuccess,
30	  onSwitchToSignIn,
31	}: SignUpFormProps) {
32	  const [step, setStep] = useState<Step>(1);
33	  const [email, setEmail] = useState("");
34	  const [fullName, setFullName] = useState("");
35	  const [password, setPassword] = useState("");
36	  const [confirmPassword, setConfirmPassword] = useState("");
37	  const [loading, setLoading] = useState(false);
38	
39	  const passwordMismatch = !!confirmPassword && password !== confirmPassword;
40	
41	  const handleStep1 = (e: React.FormEvent) => {
42	    e.preventDefault();
43	    if (!email) return;
44	    setStep(2);
45	  };
46	
47	  const handleStep2 = (e: React.FormEvent) => {
48	    e.preventDefault();
49	    if (!fullName) return;
50	    setStep(3);
51	  };
52	
53	  const handleStep3 = async (e: React.FormEvent) => {
54	    e.preventDefault();
55	    if (passwordMismatch) {
56	      toast.error("Passwords do not match");
57	      return;
58	    }
59	    if (password.length < 6) {
60	      toast.error("Password must be at least 6 characters");
61	      return;
62	    }
63	
64	    setLoading(true);
65	    try {
66	      const { error } = await supabase.auth.signUp({
67	        email,
68	        password,
69	        options: {
70	          emailRedirectTo: window.location.origin,
71	          data: { full_name: fullName },
72	        },
73	      });
74	      if (error) {
75	        toast.error(error.message);
76	      } else {
77	        toast.success("Check your email to confirm your account!");
78	        onSuccess?.();
79	      }
80	    } catch {
81	      toast.error("An unexpected error occurred. Please try again.");
82	    } finally {
83	      setLoading(false);
84	    }
85	  };
86	
87	  const hasSso = config.google_auth_enabled || config.microsoft_auth_enabled;
88	
89	  return (
90	    <div className="flex w-full flex-col justify-center bg-background px-6 py-10 sm:px-10 lg:px-14">
91	      <div className="mx-auto w-full max-w-[400px]">
92	        {/* Mobile logo */}
93	        <div className="mb-8 flex items-center gap-2.5 md:hidden">
94	          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-auth-accent to-auth-accent/80 text-sm font-extrabold text-white">
95	            R
96	          </div>
97	          <span className="text-xl font-bold tracking-tight text-foreground">
98	            Rankora
99	          </span>
100	        </div>
101	
102	        {/* Step indicator */}
103	        <div
104	          className="mb-6 flex items-center gap-2"
105	          role="progressbar"
106	          aria-valuenow={step}
107	          aria-valuemin={1}
108	          aria-valuemax={3}
109	          aria-label={`Step ${step} of 3`}
110	        >
111	          {([1, 2, 3] as const).map((s) => (
112	            <div
113	              key={s}
114	              className={`h-2 rounded-full transition-all duration-300 ${
115	                s === step
116	                  ? "w-6 bg-auth-accent"
117	                  : s < step
118	                    ? "w-2 bg-success"
119	                    : "w-2 bg-border"
120	              }`}
121	            />
122	          ))}
123	        </div>
124	
125	        {/* Header */}
126	        <div className="mb-7">
127	          <h1 className="text-2xl font-bold tracking-tight text-foreground sm:text-3xl">
128	            {config.signup_heading}
129	          </h1>
130	          <p className="mt-1.5 text-sm text-muted-foreground">
131	            Step {step} of 3 — {STEP_LABELS[step]}
132	          </p>
133	        </div>
134	
135	        {/* Step 1: Email only */}
136	        {step === 1 && (
137	          <>
138	            <SocialAuthButtons
139	              googleEnabled={config.google_auth_enabled}
140	              microsoftEnabled={config.microsoft_auth_enabled}
141	              mode="signup"
142	              disabled={loading}
143	            />
144	
145	            {hasSso && (
146	              <div className="my-5">
147	                <Divider />
148	              </div>
149	            )}
150	
151	            <form onSubmit={handleStep1} className="space-y-4">
152	              <div className="space-y-1.5">
153	                <label
154	                  htmlFor="signup-email"
155	                  className="text-sm font-medium text-foreground"
156	                >
157	                  Work email
158	                </label>
159	                <Input
160	                  id="signup-email"
161	                  type="email"
162	                  value={email}
163	                  onChange={(e) => setEmail(e.target.value)}
164	                  placeholder="name@company.com"
165	                  autoComplete="email"
166	                  autoFocus
167	                  required
168	                  className="h-11 rounded-lg"
169	                />
170	              </div>
171	
172	              <button
173	                type="submit"
174	                className="flex w-full items-center justify-center rounded-lg bg-auth-accent px-4 py-3 text-sm font-semibold text-white transition-all hover:-translate-y-px hover:bg-auth-accent-hover hover:shadow-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 active:translate-y-0"
175	              >
176	                Continue <span aria-hidden="true">&rarr;</span>
177	              </button>
178	            </form>
179	          </>
180	        )}
181	
182	        {/* Step 2: Full name */}
183	        {step === 2 && (
184	          <form onSubmit={handleStep2} className="space-y-4">
185	            <div className="space-y-1.5">
186	              <label
187	                htmlFor="signup-name"
188	                className="text-sm font-medium text-foreground"
189	              >
190	                Full name
191	              </label>
192	              <Input
193	                id="signup-name"
194	                type="text"
195	                value={fullName}
196	                onChange={(e) => setFullName(e.target.value)}
197	                placeholder="Jane Smith"
198	                autoComplete="name"
199	                autoFocus
200	                required
201	                className="h-11 rounded-lg"
202	              />
203	            </div>
204	
205	            <div className="flex gap-3">
206	              <button
207	                type="button"
208	                onClick={() => setStep(1)}
209	                className="flex-1 rounded-lg border border-border px-4 py-3 text-sm font-medium text-foreground transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
210	              >
211	                Back
212	              </button>
213	              <button
214	                type="submit"
215	                className="flex flex-[2] items-center justify-center rounded-lg bg-auth-accent px-4 py-3 text-sm font-semibold text-white transition-all hover:-translate-y-px hover:bg-auth-accent-hover hover:shadow-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 active:translate-y-0"
216	              >
217	                Continue <span aria-hidden="true">&rarr;</span>
218	              </button>
219	            </div>
220	          </form>
221	        )}
222	
223	        {/* Step 3: Password */}
224	        {step === 3 && (
225	          <form onSubmit={handleStep3} className="space-y-4">
226	            <div className="space-y-1.5">
227	              <label
228	                htmlFor="signup-password"
229	                className="text-sm font-medium text-foreground"
230	              >
231	                Password
232	              </label>
233	              <Input
234	                id="signup-password"
235	                type="password"
236	                value={password}
237	                onChange={(e) => setPassword(e.target.value)}
238	                placeholder="Min 6 characters"
239	                autoComplete="new-password"
240	                autoFocus
241	                required
242	                disabled={loading}
243	                minLength={6}
244	                className="h-11 rounded-lg"
245	              />
246	              <p className="text-xs text-muted-foreground">
247	                At least 6 characters required
248	              </p>
249	            </div>
250	
251	            <div className="space-y-1.5">
252	              <label
253	                htmlFor="signup-confirm-password"
254	                className="text-sm font-medium text-foreground"
255	              >
256	                Confirm password
257	              </label>
258	              <Input
259	                id="signup-confirm-password"
260	                type="password"
261	                value={confirmPassword}
262	                onChange={(e) => setConfirmPassword(e.target.value)}
263	                placeholder="Repeat password"
264	                autoComplete="new-password"
265	                required
266	                disabled={loading}
267	                minLength={6}
268	                aria-invalid={passwordMismatch}
269	                aria-describedby={
270	                  passwordMismatch ? "password-mismatch-error" : undefined
271	                }
272	                className={`h-11 rounded-lg ${passwordMismatch ? "border-destructive focus-visible:ring-destructive" : ""}`}
273	              />
274	              {passwordMismatch && (
275	                <p
276	                  id="password-mismatch-error"
277	                  className="text-xs text-destructive"
278	                  role="alert"
279	                >
280	                  Passwords do not match
281	                </p>
282	              )}
283	            </div>
284	
285	            <div className="flex gap-3">
286	              <button
287	                type="button"
288	                onClick={() => setStep(2)}
289	                className="flex-1 rounded-lg border border-border px-4 py-3 text-sm font-medium text-foreground transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
290	              >
291	                Back
292	              </button>
293	              <button
294	                type="submit"
295	                disabled={loading || passwordMismatch}
