3	import { useEffect, useCallback, useState, useMemo } from "react";
4	import { useRouter, useSearchParams } from "next/navigation";
5	import { useAuth } from "@/hooks/useAuth";
6	import { supabase } from "@/integrations/supabase/client";
7	import { toast } from "sonner";
8	import { useAuthPageConfig } from "@/hooks/useAuthPageConfig";
9	import { AuthLayout } from "@/components/auth/AuthLayout";
10	import { AuthLeftPanel } from "@/components/auth/AuthLeftPanel";
11	import { SignInForm } from "@/components/auth/SignInForm";
12	import { SignUpForm } from "@/components/auth/SignUpForm";
13	import { ForgotPasswordForm } from "@/components/auth/ForgotPasswordForm";
14	
15	type AuthView = "signin" | "signup" | "forgot-password";
16	
17	const Auth = () => {
18	  const { user, loading } = useAuth();
19	  const { config, isLoading: configLoading } = useAuthPageConfig();
20	  const router = useRouter();
21	  const searchParams = useSearchParams();
22	  const inviteToken = searchParams?.get("invite") ?? null;
23	  const tabParam = searchParams?.get("tab");
24	
25	  // Open-redirect protection: only allow same-origin paths starting with
26	  // a single "/" (not "//" or "/\" which can become protocol-relative).
27	  const rawNext = searchParams?.get("next") ?? "/";
28	  const nextPath = /^\/(?![/\\])/.test(rawNext) ? rawNext : "/";
29	
30	  const [view, setView] = useState<AuthView>(
31	    tabParam === "signup" ? "signup" : "signin",
32	  );
33	
34	  // ── Team invite handler ────────────────────────────────────────────
35	  const acceptInvite = useCallback(
36	    async (token: string) => {
37	      try {
38	        const {
39	          data: { session },
40	        } = await supabase.auth.getSession();
41	        if (!session?.access_token) return;
42	
43	        const res = await fetch(
44	          `${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/accept-team-invite`,
45	          {
46	            method: "POST",
47	            headers: {
48	              "Content-Type": "application/json",
49	              Authorization: `Bearer ${session.access_token}`,
50	              apikey: process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ?? "",
51	            },
52	            body: JSON.stringify({ token }),
53	          },
54	        );
55	
56	        const json = await res.json();
57	        if (res.ok && json.success) {
58	          toast.success(`Joined team: ${json.team_name ?? "Team"}`);
59	          router.replace("/team");
60	          return;
61	        }
62	      } catch {
63	        // Silently fail — user can accept invite manually later
64	      }
65	      router.replace(nextPath);
66	    },
67	    [router, nextPath],
68	  );
69	
70	  // ── Redirect authenticated users ──────────────────────────────────
71	  useEffect(() => {
72	    if (!loading && user) {
73	      if (inviteToken) {
74	        acceptInvite(inviteToken);
75	      } else {
76	        router.replace(nextPath);
77	      }
78	    }
79	  }, [user, loading, router, inviteToken, acceptInvite, nextPath]);
80	
81	  // ── Auth success callback ─────────────────────────────────────────
82	  const handleSuccess = useCallback(() => {
83	    if (inviteToken) {
84	      acceptInvite(inviteToken);
85	    } else {
86	      router.replace(nextPath);
87	    }
88	  }, [inviteToken, acceptInvite, router, nextPath]);
89	
90	  // ── Memoize left panel variant to prevent unnecessary re-renders ──
91	  const leftVariant = view === "signup" ? "signup" : "signin";
92	
93	  // Memoize left panel to avoid re-renders on form input changes
94	  const leftPanel = useMemo(
95	    () => <AuthLeftPanel config={config} variant={leftVariant} />,
96	    [config, leftVariant],
97	  );
98	
99	  // Don't render until auth state is resolved (prevents flash)
100	  if (loading) return null;
101	
102	  return (
103	    <AuthLayout
104	      left={leftPanel}
105	      right={
106	        <div className="relative w-full overflow-hidden">
107	          {/* Smooth cross-fade between views */}
108	          <div
109	            key={view}
110	            className="animate-in fade-in duration-200"
111	          >
112	            {view === "signin" && (
113	              <SignInForm
114	                config={config}
115	                onSuccess={handleSuccess}
116	                onSwitchToSignUp={() => setView("signup")}
117	                onForgotPassword={() => setView("forgot-password")}
118	              />
119	            )}
120	            {view === "signup" && (
121	              <SignUpForm
122	                config={config}
123	                onSuccess={handleSuccess}
124	                onSwitchToSignIn={() => setView("signin")}
125	              />
126	            )}
127	            {view === "forgot-password" && (
128	              <ForgotPasswordForm onBack={() => setView("signin")} />
129	            )}
130	          </div>
131	        </div>
132	      }
133	    />
134	  );
135	};
136	
137	export default Auth;
